import gurobipy as gp
from gurobipy import GRB
capacity_records = [r for r in LEGACY_RECORDS if r['source'].endswith('capacity.csv')]
product_records = [r for r in LEGACY_RECORDS if r['source'].endswith('products.csv')]
shelves = []
capacities = {}
for rec in capacity_records:
    shelf_id = str(rec['values']['resource_id'])
    shelves.append(shelf_id)
    capacities[shelf_id] = int(rec['values']['resource_capacity'])
products = []
values = {}
weights = {}
for rec in product_records:
    prod_id = str(rec['values']['item_name'])
    products.append(prod_id)
    values[prod_id] = int(rec['values']['item_value'])
    weights[prod_id] = int(rec['values']['resource_requirement'])
if len(shelves) == 0 or len(products) == 0:
    raise ValueError('No shelves or products found in LEGACY_RECORDS.')
for shelf in shelves:
    if shelf not in capacities:
        raise ValueError(f'Missing capacity for shelf {shelf}.')
for prod in products:
    if prod not in values or prod not in weights:
        raise ValueError(f'Missing value or weight for product {prod}.')
m = gp.Model('BigMart_Shelf_Allocation')
x_vars = m.addVars(shelves, products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((values[prod] * x_vars[shelf, prod] for shelf in shelves for prod in products)), GRB.MAXIMIZE)
m.addConstrs((gp.quicksum((weights[prod] * x_vars[shelf, prod] for prod in products)) <= capacities[shelf] for shelf in shelves), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
